const listCustomerUUIDs = `-- name: ListCustomerUUIDs :many
SELECT c.uuid
FROM customers c
WHERE c.organization_id = $1
  AND c.deleted_at IS NULL
  AND ($2::text[] IS NULL OR c.customer_type = ANY($2::text[]))
  AND ($3::text[] IS NULL OR c.nationality = ANY($3::text[]))
  AND ($4::text[] IS NULL OR c.tags && $4::text[])
  AND ($5::boolean IS NULL OR (c.anonymized_at IS NOT NULL) = $5::boolean)
  AND (
    $6::text[] IS NULL
    OR EXISTS (
        SELECT 1 FROM customer_marketing_consents mc
        WHERE mc.organization_id = c.organization_id AND mc.customer_id = c.id AND mc.withdrawn_at IS NULL
          AND mc.channel = ANY($6::text[])
    )
    OR ('none' = ANY($6::text[]) AND NOT EXISTS (
        SELECT 1 FROM customer_marketing_consents mc
        WHERE mc.organization_id = c.organization_id AND mc.customer_id = c.id AND mc.withdrawn_at IS NULL
    ))
  )
  AND (
    $7::text IS NULL
    OR c.first_name ILIKE '%' || $7 || '%'
    OR c.last_name ILIKE '%' || $7 || '%'
    OR (c.first_name || ' ' || c.last_name) ILIKE '%' || $7 || '%'
    OR c.company_title ILIKE '%' || $7 || '%'
    OR c.email ILIKE '%' || $7 || '%'
    OR ($8::text IS NOT NULL AND regexp_replace(c.phone, '[^0-9]', '', 'g') LIKE '%' || $8::text || '%')
    OR ($9::text[] IS NOT NULL AND c.identity_bidx = ANY($9::text[]))
  )
ORDER BY c.id ASC
LIMIT $10
`

type ListCustomerUUIDsParams struct {
	OrganizationID int64       `json:"organization_id"`
	CustomerTypes  []string    `json:"customer_types"`
	Nationalities  []string    `json:"nationalities"`
	Tags           []string    `json:"tags"`
	Anonymized     pgtype.Bool `json:"anonymized"`
	Consents       []string    `json:"consents"`
	Q              pgtype.Text `json:"q"`
	QDigits        pgtype.Text `json:"q_digits"`
	IdentityBidxs  []string    `json:"identity_bidxs"`
	LimitCount     int32       `json:"limit_count"`
}

// Bulk "all matching" scope (same filters as ListCustomers, no paging).
func (q *Queries) ListCustomerUUIDs(ctx context.Context, arg ListCustomerUUIDsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, listCustomerUUIDs,
		arg.OrganizationID,
		arg.CustomerTypes,
		arg.Nationalities,
		arg.Tags,
		arg.Anonymized,
		arg.Consents,
		arg.Q,
		arg.QDigits,
		arg.IdentityBidxs,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var uuid uuid.UUID
		if err := rows.Scan(&uuid); err != nil {
			return nil, err
		}
		items = append(items, uuid)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

